// Builds docs/prototypes/Sky-LIS_Prototype_Comparison.html from comparison.data.js
const fs = require('fs'), path = require('path');
const D = require('./comparison.data.js');
const esc = s => String(s ?? '').replace(/[&<>"]/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[m]));
const list = a => `<ul>${a.map(x => `<li>${esc(x)}</li>`).join('')}</ul>`;
const chips = a => a.map(x => `<span class="chip">${esc(x)}</span>`).join('');
const tag = m => `<span class="tag">${esc(m)}</span>`;
const stats = { cEnh: D.client.enhanced.length, cNew: D.client.added.length, cMod: D.client.modules.length, aEnh: D.admin.enhanced.length, aNew: D.admin.added.length, aMod: D.admin.modules.length };
let n = 0, sub = 0; const toc = [];
const h2 = (title, id) => { n++; sub = 0; toc.push([n, title, id, 2]); return `<h2 id="${id}"><span class="num">${n}.</span> ${esc(title)}</h2>`; };
const h3 = (title, id) => { sub++; toc.push([`${n}.${sub}`, title, id, 3]); return `<h3 id="${id}"><span class="num">${n}.${sub}</span> ${esc(title)}</h3>`; };
const enhancedTbl = rows => `<table class="cmp"><thead><tr><th class="c1">Old page</th><th class="c2">New page</th><th class="c3">Module</th><th class="c4">Enhancements</th><th class="c5">Dependencies</th></tr></thead><tbody>${rows.map(([o, nw, m, e, d]) => `<tr><td><b>${esc(o)}</b></td><td><b>${esc(nw)}</b></td><td>${tag(m)}</td><td>${list(e)}</td><td>${chips(d)}</td></tr>`).join('')}</tbody></table>`;
const addedTbl = rows => `<table class="cmp"><thead><tr><th class="c2">New page</th><th class="c3">Module</th><th class="c4">Description</th><th class="c5">Dependencies</th></tr></thead><tbody>${rows.map(([p, m, d, dep]) => `<tr><td><b>${esc(p)}</b></td><td>${tag(m)}</td><td>${esc(d)}</td><td>${chips(dep)}</td></tr>`).join('')}</tbody></table>`;
const modulesTbl = rows => `<table class="cmp"><thead><tr><th class="c2">New module</th><th class="c4">Description</th><th class="c4">Pages</th><th class="c5">Dependencies</th></tr></thead><tbody>${rows.map(([m, d, p, dep]) => `<tr><td><b>${esc(m)}</b></td><td>${esc(d)}</td><td>${chips(p)}</td><td>${chips(dep)}</td></tr>`).join('')}</tbody></table>`;

let body = `<section class="cover"><div class="kicker">${esc(D.meta.docId)} · Version ${esc(D.meta.version)} · ${esc(D.meta.date)}</div><h1>${esc(D.meta.title)}</h1><p class="sub">${esc(D.meta.subtitle)}</p>
<table class="meta"><tr><th>Prepared for</th><td>${esc(D.meta.preparedFor)}</td><th>Prepared by</th><td>${esc(D.meta.preparedBy)}</td></tr><tr><th>Compared</th><td colspan="3">Client Portal v1 → v2 · Super Admin Portal v2 → v3</td></tr><tr><th>Sources</th><td colspan="3">${D.meta.sources.map(esc).join(' · ')}</td></tr></table>
<div class="stats"><div class="stat"><strong>${stats.cEnh}</strong><span>Client pages enhanced</span></div><div class="stat"><strong>${stats.cNew}</strong><span>Client pages added</span></div><div class="stat"><strong>${stats.cMod}</strong><span>Client modules added</span></div><div class="stat"><strong>${stats.aEnh}</strong><span>Admin pages enhanced</span></div><div class="stat"><strong>${stats.aNew}</strong><span>Admin pages added</span></div><div class="stat"><strong>${stats.aMod}</strong><span>Admin modules added</span></div></div>
<p class="note">Reading guide: "Enhancements" lists what changed on a page that already existed in the old prototype. "Dependencies" names the master data, other pages or modules a page needs in order to work (what must be set up first, or what it reads from). "—" means the page depends only on itself.</p></section>`;
body += `<section>${h2('Cross-cutting enhancements (both portals)', 'cross')}<table class="cmp"><thead><tr><th class="c2">Area</th><th class="c4">What changed</th><th class="c5">Dependencies</th></tr></thead><tbody>${D.crossCutting.map(([a, w, d]) => `<tr><td><b>${esc(a)}</b></td><td>${esc(w)}</td><td>${chips(d.split(', '))}</td></tr>`).join('')}</tbody></table></section>`;
body += `<section>${h2('Client Portal — v1 to v2', 'client')}${h3('Pages that existed and were enhanced', 'client-enh')}${enhancedTbl(D.client.enhanced)}${h3('New pages', 'client-new')}${addedTbl(D.client.added)}${h3('New modules', 'client-mod')}${modulesTbl(D.client.modules)}</section>`;
body += `<section>${h2('Super Admin Portal — v2 to v3', 'admin')}${h3('Pages that existed and were enhanced', 'admin-enh')}${enhancedTbl(D.admin.enhanced)}${h3('New pages', 'admin-new')}${addedTbl(D.admin.added)}${h3('New modules', 'admin-mod')}${modulesTbl(D.admin.modules)}</section>`;
body += `<section>${h2('Dependency map — what to set up first', 'order')}<ol class="order"><li><b>Platform (Super Admin):</b> countries and governorates → plans → clients (master-data copy generated) → integration library, code systems, rule templates, notification templates, platform parameters.</li><li><b>Tenant foundation:</b> branches → roles → users (treasury requests per device) → parameters.</li><li><b>Catalogue:</b> sample types and conditions → units → clinical groups and report templates → tests → services (members) → patient conditions, preparations, comment library, diagnoses, shortcut sets, test rules, reasons, additional services, doctors, sending labs.</li><li><b>Pricing:</b> base price lists → payers with tiers → contract pricing (apply).</li><li><b>Integration & automation:</b> analysers → analyser tests and sample codes → site agent → PCR kits → verification settings → medical rules.</li><li><b>Operations:</b> registration (walk-in, home, batch, lab-to-lab) → samples → worklist / results / work queue → printing → payments, refunds, transfers, cancellations, cash closing, claims and reports.</li></ol></section>`;
const tocHtml = `<nav class="toc"><div class="toc-title">Contents</div><ol>${toc.map(([k, t, id, l]) => `<li class="lvl${l}"><a href="#${id}"><span class="num">${k}</span> ${esc(t)}</a></li>`).join('')}</ol></nav>`;
const css = `:root{--ink:#14213A;--ink-2:#3C4A63;--muted:#6B7A90;--line:#DCE3EE;--line-soft:#EAEFF6;--bg:#F3F6FB;--paper:#fff;--navy:#0B2A5B;--blue:#2A7DF5;--violet:#6E3BE4;--grad:linear-gradient(90deg,#2A7DF5,#6E3BE4);--blue-soft:#E8F1FE;--violet-soft:#EFE9FD}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14.5px/1.55 "Segoe UI",Tahoma,system-ui,sans-serif}.page{max-width:1280px;margin:0 auto;padding:28px 22px 80px}.paper{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:44px 52px;box-shadow:0 1px 2px rgba(11,42,91,.05),0 12px 32px -20px rgba(11,42,91,.25)}
.cover{border-bottom:3px solid transparent;border-image:var(--grad) 1;padding-bottom:24px;margin-bottom:28px}.kicker{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--violet);font-weight:700}h1{font-size:32px;color:var(--navy);margin:6px 0 4px}.sub{color:var(--ink-2);max-width:70rem;margin:0 0 18px;font-size:15px}
table{border-collapse:collapse;width:100%;font-size:13px;margin:10px 0 22px}th,td{border:1px solid var(--line);padding:8px 10px;vertical-align:top;text-align:left}thead th{background:var(--blue-soft);color:var(--navy);font-size:12px;letter-spacing:.02em;position:sticky;top:0}tbody tr:nth-child(even) td{background:#fafbfd}
table.meta th{width:12%;background:var(--line-soft);color:var(--ink-2)}table.meta td{width:38%}
.stats{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0 10px}.stat{flex:1 1 150px;background:var(--violet-soft);border:1px solid #D9CCF8;border-radius:10px;padding:10px 14px}.stat strong{display:block;font-size:24px;color:var(--navy);line-height:1.1}.stat span{font-size:12px;color:var(--ink-2)}
.toc{background:var(--line-soft);border:1px solid var(--line);border-radius:10px;padding:16px 20px;margin:0 0 30px}.toc-title{font-weight:700;color:var(--navy);text-transform:uppercase;letter-spacing:.06em;font-size:13px;margin-bottom:6px}.toc ol{list-style:none;margin:0;padding:0;columns:2;column-gap:30px}.toc li{padding:2px 0;font-size:13.5px}.toc li.lvl3{padding-left:20px;font-size:13px}.toc a{color:var(--ink);text-decoration:none}.toc .num{display:inline-block;min-width:2.6em;color:var(--muted)}
h2{font-size:23px;color:var(--navy);border-bottom:1px solid var(--line);padding-bottom:8px;margin:40px 0 14px}h3{font-size:16px;margin:26px 0 6px}h2 .num,h3 .num{color:var(--blue);margin-right:6px}
table.cmp .c1{width:12%}table.cmp .c2{width:13%}table.cmp .c3{width:9%}table.cmp .c4{width:42%}table.cmp .c5{width:24%}
table.cmp ul{margin:0;padding-left:16px}table.cmp li{margin:2px 0}
.chip{display:inline-block;background:var(--line-soft);border:1px solid var(--line);border-radius:999px;padding:1px 8px;font-size:11.5px;margin:1px 2px 1px 0;color:var(--ink-2)}.tag{display:inline-block;background:var(--violet-soft);color:#5B2ACB;border-radius:6px;padding:1px 7px;font-size:11.5px;font-weight:600;white-space:nowrap}
.note{font-size:13px;color:var(--muted);border-left:3px solid var(--line);padding-left:12px}.order li{margin:6px 0}
.footer{margin-top:36px;padding-top:12px;border-top:1px solid var(--line);font-size:12px;color:var(--muted);display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}
@media (max-width:900px){.paper{padding:22px 16px}.toc ol{columns:1}table.cmp .c1,table.cmp .c2,table.cmp .c3,table.cmp .c4,table.cmp .c5{width:auto}}
@media print{body{background:#fff;font-size:11px}.page{padding:0;max-width:none}.paper{border:0;box-shadow:none;padding:0}h2{break-before:page}thead{display:table-header-group}tr{break-inside:avoid}@page{size:A4 landscape;margin:12mm}}`;
const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(D.meta.title)} — ${esc(D.meta.docId)} v${esc(D.meta.version)}</title><style>${css}</style></head><body><div class="page"><div class="paper">${body.split('<section>')[0]}${tocHtml}${body.split('<section>').slice(1).map(s => '<section>' + s).join('')}<div class="footer"><span>${esc(D.meta.title)} · ${esc(D.meta.docId)} v${esc(D.meta.version)}</span><span>Generated from docs/prototypes/src/comparison.data.js on ${esc(D.meta.date)}</span></div></div></div></body></html>`;
const out = path.join(__dirname, '..', 'Sky-LIS_Prototype_Comparison.html');
fs.writeFileSync(out, html, 'utf8');
console.log(`Wrote ${out} (${(html.length / 1024).toFixed(0)} KB) — client: ${stats.cEnh} enhanced, ${stats.cNew} new pages, ${stats.cMod} modules · admin: ${stats.aEnh} enhanced, ${stats.aNew} new pages, ${stats.aMod} modules`);
